from __future__ import annotations
import json,sys
from dataclasses import fields,replace
from pathlib import Path
from typing import Any
sys.path.insert(0,str(Path.cwd()))
import torch
from benchmarks.cases import CASES
from pinnstorch.api import Coordinates,Equation,TensorFields
from pinnstorch.runner.factory import SolverFactory
from pinnstorch.runner.problem import load_problem
from pinnstorch.runner.settings import TaskSettings
from pinnstorch.training.robin_box import BoxRobinInitial,BoundBoxRobinInitial
from pinnstorch.training.robin_initial import IntervalRobinInitial,BoundRobinInitial

class StaticBoxBackground(BoxRobinInitial):
 def background(self,spatial:list[torch.Tensor],time:torch.Tensor)->TensorFields:
  return self.initial(spatial,torch.full_like(time,self.time_interval[0]))

class StaticIntervalBackground(IntervalRobinInitial):
 def background(self,x:torch.Tensor,time:torch.Tensor)->TensorFields:
  return self.initial([x],torch.full_like(time,self.time_interval[0]))

def constant_initial(c:Coordinates)->TensorFields:
 return {'u':torch.ones_like(c.t)}

def flux_initial(c:Coordinates)->TensorFields:
 value=torch.ones_like(c.t)
 for x in c.spatial.values():value=value+x
 return {'u':value}

def static_transform(settings:TaskSettings,bound:Any)->Any:
 if any(b.value_function is not None for b in settings.boundaries):
  raise ValueError('Static numeric data required; callbacks cannot be inferred constant')
 if not isinstance(bound,(BoundRobinInitial,BoundBoxRobinInitial)):
  raise ValueError('Exact Robin/Neumann transform required')
 recipe=bound.recipe
 kwargs={f.name:getattr(recipe,f.name) for f in fields(recipe) if f.init}
 cls=StaticBoxBackground if isinstance(recipe,BoxRobinInitial) else StaticIntervalBackground
 return cls(**kwargs).bind(bound.network)

import hashlib,statistics,time
from scripts.benchmark_robin_execution import load_model,objective
from benchmarks.performance import prediction_speed

torch.set_num_threads(1)
torch.backends.cuda.matmul.allow_tf32=False
torch.backends.cudnn.allow_tf32=False
torch.set_float32_matmul_precision('highest')
trial=Path('numerical-reports/polynomial-neumann-baseline-001/seed-19/heat_neumann_polynomial2d-19')
factory,model=load_model(trial,'robin_grouped','recursive','cuda')
original=model.output_fn
shortcut=static_transform(factory.settings,original)
transforms={'recursive':original,'static_background':shortcut}
generator=torch.Generator().manual_seed(20261016)
points=torch.rand((256,3),generator=generator).to('cuda');points[:,-1]*=.5

def evaluate(transform:Any)->tuple[torch.Tensor,...]:
 model.output_fn=transform
 columns=[points[:,i:i+1].detach().requires_grad_() for i in range(3)]
 output=dict(model(columns[:-1],columns[-1]))
 e=Equation(output,Coordinates(dict(zip('xy',columns[:-1])),columns[-1]))
 residual=factory.adapter.residuals(output,*columns)['heat']
 derivatives=(output['u'],e.dt('u'),e.laplacian('u'),residual)
 gradients=torch.autograd.grad(residual.square().mean(),tuple(model.parameters()))
 return tuple(x.detach().clone() for x in (*derivatives,*gradients))

for _ in range(3):
 for transform in transforms.values():evaluate(transform)
a=evaluate(original);a_repeat=evaluate(original);b=evaluate(shortcut)
for x,y in zip(a,b):torch.testing.assert_close(x,y,rtol=3e-5,atol=3e-5)
comparisons=dict(reference_self_exact=all(torch.equal(x,y) for x,y in zip(a,a_repeat)),all_tensors_exact=all(torch.equal(x,y) for x,y in zip(a,b)),max_abs_difference=max(float((x-y).abs().max()) for x,y in zip(a,b)))
measurements=[]
for index in range(3):
 for name in (list(transforms) if index%2==0 else list(reversed(transforms))):
  model.output_fn=transforms[name];durations=[]
  for iteration in range(10):
   model.zero_grad(set_to_none=True);torch.cuda.synchronize();started=time.perf_counter()
   torch.autograd.backward(objective(factory,model,points),inputs=tuple(model.parameters()))
   torch.cuda.synchronize()
   if iteration>=3:durations.append(time.perf_counter()-started)
  measurements.append(dict(repetition=index,variant=name,objective_backward_seconds_median=statistics.median(durations),objective_backward_min_seconds=min(durations),objective_backward_max_seconds=max(durations)))
prediction_points=torch.rand((4096,3),generator=generator).to('cuda');prediction_points[:,-1]*=.5
for index in range(3):
 for name in (list(transforms) if index%2==0 else list(reversed(transforms))):
  model.output_fn=transforms[name]
  performance=prediction_speed(model,[prediction_points[:,:1],prediction_points[:,1:2]],prediction_points[:,2:3],512)
  measurements.append(dict(repetition=index,variant=name,**performance))
report=dict(contract=1,device='cuda',gpu=torch.cuda.get_device_name(0),torch=torch.__version__,checkpoint_sha256=hashlib.sha256((trial/'training/checkpoints/final.ckpt').read_bytes()).hexdigest(),comparisons=comparisons,measurements=measurements,points=256,precision='FP32, TF32 off',backward='parameters',limitations='Experimental explicit-constant operator-data background override on one frozen polynomial 2D checkpoint. No training/optimizer update; not a time-to-quality test. Three alternating repetitions, three warmups/seven measurements. Not integrated into production. Numeric data verified, arbitrary callbacks rejected.')
Path('numerical-reports/static-background-gpu-probe-001.json').write_text(json.dumps(report,indent=2,allow_nan=False))
print(json.dumps(report,indent=2))
